
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_c_op_b88_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_c_op_b88", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-5.922569717983987e-02, -5.891368995510145e-02, -5.845374497242466e-02, -5.776877586268811e-02, -5.673438609814414e-02, -5.514353409411700e-02, -5.264301422488828e-02, -4.863630165620813e-02, -4.225761741914594e-02, -3.316853374582678e-02, -2.519135599782477e-02, -2.938076763662233e-02, -3.536275025598195e-02, -2.789493982418467e-02, -1.713913509097256e-02, -6.714379411345054e-03, -1.182938556461699e-03, -5.879613220228254e-05, -4.478076108070879e-07, -2.856817729857987e-10]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


